from pydantic import BaseModel, Field


class DocumentInfo(BaseModel):
    title: str | None = Field(description="The full title of the legal document as found in the text")
    case_cause: str | None = Field(description="The official legal case cause (案由) identified in the document")


class Parse(BaseModel):
    documents: list[DocumentInfo] = Field(description="Extraction results for the input legal document")
